dashboard.definition:
{
  "dataSources": {
    "ds_wordmark": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval brand=\"splunk\"" },
      "name": "Wordmark"
    },
    "ds_kpi_notables": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"Notable events (24h)\", value=1247, unit=\"\", delta=\"+83\", deltaDir=\"up\", sparkline=\"980,1020,1050,1100,1080,1150,1200,1247\"" },
      "name": "KPI Notables"
    },
    "ds_kpi_response": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"Mean response time\", value=247.1, unit=\"ms\", delta=\"-12.3\", deltaDir=\"down\", sparkline=\"310,290,275,260,255,250,248,247\"" },
      "name": "KPI Response"
    },
    "ds_kpi_users": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"Active users\", value=3842, unit=\"\", delta=\"+156\", deltaDir=\"up\", sparkline=\"3200,3350,3400,3500,3600,3700,3780,3842\"" },
      "name": "KPI Users"
    },
    "ds_kpi_errors": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"Error rate\", value=2.4, unit=\"%\", delta=\"+0.3\", deltaDir=\"up\", sparkline=\"1.8,1.9,2.0,2.1,2.0,2.2,2.3,2.4\"" },
      "name": "KPI Errors"
    },
    "ds_kpi_uptime": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"Uptime\", value=99.97, unit=\"%\", delta=\"+0.02\", deltaDir=\"up\", sparkline=\"99.90,99.91,99.93,99.94,99.95,99.96,99.96,99.97\"" },
      "name": "KPI Uptime"
    },
    "ds_chip_header": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"Notables\", value=\"1247\"" },
      "name": "Chip Header"
    },
    "ds_chip_badge": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"Critical\", value=\"23\"" },
      "name": "Chip Badge"
    },
    "ds_chip_service": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval label=\"API Gateway\", value=\"ok\"" },
      "name": "Chip Service"
    },
    "ds_sparkline": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=20 | streamstats count as i | eval count=random() % 80 + 20 | table i count" },
      "name": "Sparkline"
    },
    "ds_area": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=24 | streamstats count as i | eval _time=relative_time(now(), \"-24h+\".i.\"h\"), notable=random() % 40 + 15, blocked=random() % 25 + 5, auth_fail=random() % 18 + 3 | table _time notable blocked auth_fail" },
      "name": "Area Chart"
    },
    "ds_column": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=7 | streamstats count as i | eval category=case(i==1,\"Mon\",i==2,\"Tue\",i==3,\"Wed\",i==4,\"Thu\",i==5,\"Fri\",i==6,\"Sat\",1==1,\"Sun\"), count=case(i==1,45,i==2,62,i==3,38,i==4,71,i==5,55,i==6,28,1==1,33) | table category count" },
      "name": "Column Chart"
    },
    "ds_gauge_risk": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval value=62" },
      "name": "Gauge Risk"
    },
    "ds_gauge_cpu": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval value=68" },
      "name": "Gauge CPU"
    },
    "ds_gauge_mem": {
      "type": "ds.search",
      "options": { "query": "| makeresults | eval value=74" },
      "name": "Gauge Memory"
    },
    "ds_donut": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=4 | streamstats count as i | eval region=case(i==1,\"North America\",i==2,\"EMEA\",i==3,\"APAC\",1==1,\"LATAM\"), amount=case(i==1,4250000,i==2,3180000,i==3,2100000,1==1,1420000) | table region amount" },
      "name": "Donut"
    },
    "ds_hbar": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=7 | streamstats count as i | eval source=case(i==1,\"firewall.corp.local\",i==2,\"proxy-east.prod\",i==3,\"ids-sensor-01\",i==4,\"dns-resolver\",i==5,\"vpn-gateway\",i==6,\"mail-relay\",1==1,\"web-app-01\"), count=case(i==1,4521,i==2,3102,i==3,2847,i==4,1903,i==5,1456,i==6,892,1==1,341) | table source count" },
      "name": "H-Bar List"
    },
    "ds_funnel": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=5 | streamstats count as i | eval stage=case(i==1,\"Visits\",i==2,\"Signups\",i==3,\"Trials\",i==4,\"Purchases\",1==1,\"Renewals\"), count=case(i==1,10000,i==2,3200,i==3,1800,i==4,900,1==1,620) | table stage count" },
      "name": "Funnel"
    },
    "ds_heatmap": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=25 | streamstats count as i | eval row_label=case(i%5==1,\"Initial Access\",i%5==2,\"Execution\",i%5==3,\"Persistence\",i%5==4,\"Privilege Escalation\",1==1,\"Lateral Movement\"), col_label=case(i<=5,\"Mon\",i<=10,\"Tue\",i<=15,\"Wed\",i<=20,\"Thu\",1==1,\"Fri\"), count=random() % 12 | table row_label col_label count" },
      "name": "Heatmap"
    },
    "ds_table": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=8 | streamstats count as i | eval _time=relative_time(now(), \"-\".i*5.\"m\"), severity=case(i%4==0,\"Critical\",i%4==1,\"High\",i%4==2,\"Medium\",1==1,\"Low\"), event=case(i%4==0,\"Brute force attempt on admin\",i%4==1,\"Malware signature match\",i%4==2,\"Failed login attempts > 10\",1==1,\"Port scan detected\"), source=case(i%3==0,\"firewall.corp\",i%3==1,\"ids-sensor-01\",1==1,\"proxy-east\") | table _time severity event source" },
      "name": "Data Table"
    },
    "ds_popgrid": {
      "type": "ds.search",
      "options": { "query": "| makeresults count=16 | streamstats count as i | eval site_code=case(i==1,\"IAD\",i==2,\"SJC\",i==3,\"LHR\",i==4,\"FRA\",i==5,\"NRT\",i==6,\"SYD\",i==7,\"GRU\",i==8,\"CDG\",i==9,\"SIN\",i==10,\"ORD\",i==11,\"DFW\",i==12,\"SEA\",i==13,\"MIA\",i==14,\"YYZ\",i==15,\"AMS\",1==1,\"BOM\"), site_name=case(i==1,\"Ashburn\",i==2,\"San Jose\",i==3,\"London\",i==4,\"Frankfurt\",i==5,\"Tokyo\",i==6,\"Sydney\",i==7,\"Sao Paulo\",i==8,\"Paris\",i==9,\"Singapore\",i==10,\"Chicago\",i==11,\"Dallas\",i==12,\"Seattle\",i==13,\"Miami\",i==14,\"Toronto\",i==15,\"Amsterdam\",1==1,\"Mumbai\"), status=case(i==6,\"critical\",i==3,\"warn\",i==9,\"warn\",i==13,\"degraded\",1==1,\"ok\"), util=case(i==6,92,i==3,78,i==9,71,i==13,67,i==1,64,i==5,55,i==2,52,i==16,58,i==14,51,i==8,47,i==12,44,i==4,41,i==15,36,i==10,33,i==11,29,1==1,38) | table site_code site_name status util" },
      "name": "PoP Grid"
    }
  },
  "visualizations": {
    "viz_wordmark": {
      "type": "super_co_viz.wordmark",
      "options": { "theme": "dark", "subMark": "Enterprise Security", "align": "center" },
      "dataSources": { "primary": "ds_wordmark" },
      "title": "Wordmark"
    },
    "viz_kpi_notables": {
      "type": "super_co_viz.single_value_tile",
      "options": { "theme": "dark", "labelField": "label", "valueField": "value", "unitField": "unit", "deltaField": "delta", "deltaDirField": "deltaDir", "deltaSemantics": "down-good", "showSparkline": "true", "sparklineField": "sparkline", "accentColor": "#e5eaf2", "deltaSubLabel": "vs prev 24h" },
      "dataSources": { "primary": "ds_kpi_notables" },
      "title": "Notable Events"
    },
    "viz_kpi_response": {
      "type": "super_co_viz.single_value_tile",
      "options": { "theme": "dark", "labelField": "label", "valueField": "value", "unitField": "unit", "deltaField": "delta", "deltaDirField": "deltaDir", "deltaSemantics": "down-good", "showSparkline": "true", "sparklineField": "sparkline", "accentColor": "#e5eaf2", "deltaSubLabel": "vs prev 24h" },
      "dataSources": { "primary": "ds_kpi_response" },
      "title": "Response Time"
    },
    "viz_kpi_users": {
      "type": "super_co_viz.single_value_tile",
      "options": { "theme": "dark", "labelField": "label", "valueField": "value", "unitField": "unit", "deltaField": "delta", "deltaDirField": "deltaDir", "deltaSemantics": "up-good", "showSparkline": "true", "sparklineField": "sparkline", "accentColor": "#e5eaf2", "deltaSubLabel": "vs prev 24h" },
      "dataSources": { "primary": "ds_kpi_users" },
      "title": "Active Users"
    },
    "viz_kpi_errors": {
      "type": "super_co_viz.single_value_tile",
      "options": { "theme": "dark", "labelField": "label", "valueField": "value", "unitField": "unit", "deltaField": "delta", "deltaDirField": "deltaDir", "deltaSemantics": "down-good", "showSparkline": "true", "sparklineField": "sparkline", "accentColor": "#ff6600", "deltaSubLabel": "vs prev 24h" },
      "dataSources": { "primary": "ds_kpi_errors" },
      "title": "Error Rate"
    },
    "viz_kpi_uptime": {
      "type": "super_co_viz.single_value_tile",
      "options": { "theme": "dark", "labelField": "label", "valueField": "value", "unitField": "unit", "deltaField": "delta", "deltaDirField": "deltaDir", "deltaSemantics": "up-good", "showSparkline": "true", "sparklineField": "sparkline", "accentColor": "#2bbfb8", "deltaSubLabel": "vs prev 24h" },
      "dataSources": { "primary": "ds_kpi_uptime" },
      "title": "Uptime"
    },
    "viz_chip_header": {
      "type": "super_co_viz.status_chip",
      "options": { "theme": "dark", "variant": "header", "color": "#2bbfb8", "labelField": "label", "valueField": "value" },
      "dataSources": { "primary": "ds_chip_header" },
      "title": "Status Chip — Header"
    },
    "viz_chip_badge": {
      "type": "super_co_viz.status_chip",
      "options": { "theme": "dark", "variant": "badge", "color": "#d41f1f", "labelField": "label", "valueField": "value" },
      "dataSources": { "primary": "ds_chip_badge" },
      "title": "Status Chip — Badge"
    },
    "viz_chip_service": {
      "type": "super_co_viz.status_chip",
      "options": { "theme": "dark", "variant": "service", "color": "#118832", "labelField": "label", "valueField": "value" },
      "dataSources": { "primary": "ds_chip_service" },
      "title": "Status Chip — Service"
    },
    "viz_sparkline": {
      "type": "super_co_viz.sparkline",
      "options": { "color": "#2bbfb8", "strokeWidth": "1.5", "showFill": "true", "field": "count" },
      "dataSources": { "primary": "ds_sparkline" },
      "title": "Sparkline"
    },
    "viz_area": {
      "type": "super_co_viz.area_chart",
      "options": { "theme": "dark", "gridLines": "4", "showMarker": "false", "markerIndex": "-1", "markerLabel": "" },
      "dataSources": { "primary": "ds_area" },
      "title": "Threat Events Over Time"
    },
    "viz_column": {
      "type": "super_co_viz.column_chart",
      "options": { "theme": "dark", "gridLines": "4", "highlightIndex": "3", "barColor": "#2bbfb8" },
      "dataSources": { "primary": "ds_column" },
      "title": "Events by Day"
    },
    "viz_gauge_risk": {
      "type": "super_co_viz.ring_gauge",
      "options": { "theme": "dark", "field": "value", "max": "100", "thick": "10", "half": "false", "color": "#ff6600", "subLabel": "Risk Score", "showThresholds": "true", "thresholdMid": "40", "thresholdHigh": "70", "colorLow": "#118832", "colorMid": "#cba700", "colorHigh": "#d41f1f" },
      "dataSources": { "primary": "ds_gauge_risk" },
      "title": "Risk Score"
    },
    "viz_gauge_cpu": {
      "type": "super_co_viz.ring_gauge",
      "options": { "theme": "dark", "field": "value", "max": "100", "thick": "10", "half": "false", "color": "#2bbfb8", "subLabel": "CPU", "showThresholds": "false" },
      "dataSources": { "primary": "ds_gauge_cpu" },
      "title": "CPU Usage"
    },
    "viz_gauge_mem": {
      "type": "super_co_viz.ring_gauge",
      "options": { "theme": "dark", "field": "value", "max": "100", "thick": "10", "half": "true", "color": "#ff6600", "subLabel": "Memory", "showThresholds": "false" },
      "dataSources": { "primary": "ds_gauge_mem" },
      "title": "Memory (Half Arc)"
    },
    "viz_donut": {
      "type": "super_co_viz.donut",
      "options": { "theme": "dark", "labelField": "region", "valueField": "amount", "centerLabel": "", "centerSubLabel": "total · Q2", "legendPosition": "auto" },
      "dataSources": { "primary": "ds_donut" },
      "title": "Revenue by Region"
    },
    "viz_hbar": {
      "type": "super_co_viz.h_bar_list",
      "options": { "theme": "dark", "labelField": "source", "valueField": "count", "suffix": "", "spotlightIndex": "0", "maxRows": "10" },
      "dataSources": { "primary": "ds_hbar" },
      "title": "Top Alert Sources"
    },
    "viz_funnel": {
      "type": "super_co_viz.funnel",
      "options": { "theme": "dark", "labelField": "stage", "valueField": "count", "dropoffWarnThreshold": "30" },
      "dataSources": { "primary": "ds_funnel" },
      "title": "Signup Funnel"
    },
    "viz_heatmap": {
      "type": "super_co_viz.heatmap",
      "options": { "theme": "dark", "rowField": "row_label", "colField": "col_label", "valueField": "count", "showCellValues": "true", "colorMode": "severity" },
      "dataSources": { "primary": "ds_heatmap" },
      "title": "MITRE ATT&CK Coverage"
    },
    "viz_table": {
      "type": "super_co_viz.data_table",
      "options": { "theme": "dark", "maxRows": "20", "columnTypes": "", "thresholdField": "", "thresholdWarn": "50", "thresholdDanger": "80" },
      "dataSources": { "primary": "ds_table" },
      "title": "Recent Notable Events"
    },
    "viz_popgrid": {
      "type": "super_co_viz.pop_grid",
      "options": { "theme": "dark", "columns": "4", "codeField": "site_code", "nameField": "site_name", "statusField": "status", "utilField": "util" },
      "dataSources": { "primary": "ds_popgrid" },
      "title": "Global PoP Status"
    }
  },
  "layout": {
    "type": "absolute",
    "options": { "width": 1440, "height": 2200, "display": "auto-scale" },
    "structure": [
      { "item": "viz_wordmark",     "type": "block", "position": { "x": 0,    "y": 0,    "w": 1440, "h": 48  } },

      { "item": "viz_kpi_notables", "type": "block", "position": { "x": 0,    "y": 64,   "w": 276,  "h": 120 } },
      { "item": "viz_kpi_response", "type": "block", "position": { "x": 292,  "y": 64,   "w": 276,  "h": 120 } },
      { "item": "viz_kpi_users",    "type": "block", "position": { "x": 584,  "y": 64,   "w": 276,  "h": 120 } },
      { "item": "viz_kpi_errors",   "type": "block", "position": { "x": 876,  "y": 64,   "w": 276,  "h": 120 } },
      { "item": "viz_kpi_uptime",   "type": "block", "position": { "x": 1168, "y": 64,   "w": 272,  "h": 120 } },

      { "item": "viz_chip_header",  "type": "block", "position": { "x": 0,    "y": 200,  "w": 250,  "h": 50  } },
      { "item": "viz_chip_badge",   "type": "block", "position": { "x": 266,  "y": 200,  "w": 250,  "h": 50  } },
      { "item": "viz_chip_service", "type": "block", "position": { "x": 532,  "y": 200,  "w": 250,  "h": 50  } },
      { "item": "viz_sparkline",    "type": "block", "position": { "x": 798,  "y": 200,  "w": 642,  "h": 50  } },

      { "item": "viz_area",         "type": "block", "position": { "x": 0,    "y": 270,  "w": 860,  "h": 320 } },
      { "item": "viz_column",       "type": "block", "position": { "x": 876,  "y": 270,  "w": 564,  "h": 320 } },

      { "item": "viz_gauge_risk",   "type": "block", "position": { "x": 0,    "y": 610,  "w": 340,  "h": 240 } },
      { "item": "viz_gauge_cpu",    "type": "block", "position": { "x": 356,  "y": 610,  "w": 340,  "h": 240 } },
      { "item": "viz_gauge_mem",    "type": "block", "position": { "x": 712,  "y": 610,  "w": 340,  "h": 240 } },
      { "item": "viz_donut",        "type": "block", "position": { "x": 1068, "y": 610,  "w": 372,  "h": 240 } },

      { "item": "viz_hbar",         "type": "block", "position": { "x": 0,    "y": 870,  "w": 700,  "h": 300 } },
      { "item": "viz_funnel",       "type": "block", "position": { "x": 716,  "y": 870,  "w": 724,  "h": 300 } },

      { "item": "viz_heatmap",      "type": "block", "position": { "x": 0,    "y": 1190, "w": 1440, "h": 280 } },
      { "item": "viz_table",        "type": "block", "position": { "x": 0,    "y": 1490, "w": 1440, "h": 360 } },
      { "item": "viz_popgrid",      "type": "block", "position": { "x": 0,    "y": 1870, "w": 1440, "h": 320 } }
    ]
  }
}
